for row in recipes:
 p=root/row['path'];data=p.read_bytes()
 if hashlib.sha256(data).hexdigest()!=row['sha256']:raise RuntimeError('Unexpected source '+row['path'])
 s=data.decode()
 for a,b in row['edits']:
  if s.count(a)!=1:raise RuntimeError('Unexpected edit context')
  s=s.replace(a,b)
 result=s.encode()
 if hashlib.sha256(result).hexdigest()!=row['result_sha256']:raise RuntimeError('Backport verification failed')
 p.write_bytes(result)
print('Verified upstream CUDA PTX terminator backport: seven files; scoring formulas unchanged')
